<div class="page-head"><div><h1>Events</h1><p>ISF is event-based; create and activate each annual event independently.</p></div><button class="btn primary" data-modal="event-modal">+ Add Event</button></div>
<section class="panel"><div class="table-wrap"><table><thead><tr><th>#</th><th>Event Name</th><th>Year</th><th>Dates</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($events as $i=>$e): ?><tr><td><?= $i+1 ?></td><td><b><?= esc($e['name']) ?></b></td><td><?= esc($e['year']) ?></td><td><?= esc($e['start_date']?:'—') ?> to <?= esc($e['end_date']?:'—') ?></td><td><span class="badge <?= $e['is_active']?'official':'neutral' ?>"><?= $e['is_active']?'ACTIVE':'INACTIVE' ?></span></td><td><?php if(!$e['is_active']): ?><form method="post" action="<?= site_url('events/'.$e['id'].'/activate') ?>"><?= csrf_field() ?><button class="btn tiny">Activate</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<dialog id="event-modal"><form method="post" action="<?= site_url('events') ?>" class="modal-card"><?= csrf_field() ?><div class="modal-head"><h2>Add Event</h2><button type="button" data-close>×</button></div><label>Event Name<input name="name" required placeholder="Intercollegiate Students Festival 2027"></label><label>Year<input type="number" name="year" min="2000" max="2100" required value="<?= date('Y') ?>"></label><div class="form-grid"><label>Start Date<input type="date" name="start_date"></label><label>End Date<input type="date" name="end_date"></label></div><label class="check"><input type="checkbox" name="is_active" value="1"> Set as active event</label><button class="btn primary full">Save Event</button></form></dialog>
